import {useEffect,useState} from 'react';
import {ClipboardList,Loader2,RefreshCw} from 'lucide-react';
import {createProfessionPlan,getProfessionPlan,listProfessionPlans,publishProfessionPlan,saveProfessionPlan} from '../../lib/practiceOperationsApi';

const TYPE_BY_PROFESSION={PSYCHOLOGIST:'THERAPY_PLAN',PHYSIOTHERAPIST:'REHAB_PLAN',DIABETES_EDUCATOR:'DIABETES_EDUCATION_PLAN',HEALTH_COACH:'HABIT_PLAN',WELLNESS_CONSULTANT:'WELLNESS_PLAN',BEHAVIOURAL_THERAPIST:'BEHAVIOUR_INTERVENTION_PLAN',OCCUPATIONAL_THERAPIST:'OT_PLAN',MENTAL_WELLNESS_THERAPIST:'SUPPORT_PLAN'};
const label=value=>String(value||'').replaceAll('_',' ').toLowerCase().replace(/^./,letter=>letter.toUpperCase());

export function ProfessionPlanHistory({items,onOpen}){return items.length?<div className="divide-y rounded-2xl border bg-white">{items.map(item=><button key={item.id} onClick={()=>onOpen(item.id)} className="flex min-h-16 w-full items-center justify-between gap-3 p-4 text-left"><span><strong>{item.title}</strong><small className="mt-1 block text-slate-500">{label(item.plan_type)} · Version {item.current_version}</small></span><span className="rounded-full bg-blue-50 px-2.5 py-1 text-xs font-bold text-blue-700">{item.status}</span></button>)}</div>:<div className="rounded-2xl border border-dashed bg-white p-7 text-center"><ClipboardList className="mx-auto text-blue-700"/><h4 className="mt-3 font-semibold">No profession plans yet.</h4></div>}

export function ProfessionPlanPreview({detail}){return <section className="rounded-2xl border bg-slate-50 p-5"><p className="text-xs font-bold uppercase tracking-wider text-blue-700">Client-ready preview</p><h4 className="mt-2 text-xl font-bold">{detail.plan.title}</h4><div className="mt-4 space-y-3">{detail.sections.map(section=><article key={section.id} className="rounded-xl bg-white p-4"><strong>{section.title}</strong><p className="mt-2 whitespace-pre-wrap text-sm text-slate-600">{section.content?.text||'No content recorded.'}</p></article>)}</div></section>}

export function ProfessionPlanEditor({detail,onReload}){const [title,setTitle]=useState(detail.plan.title);const [text,setText]=useState(detail.sections[0]?.content?.text||'');const [busy,setBusy]=useState('');const [error,setError]=useState('');const locked=detail.plan.status==='PUBLISHED';const payload={title,expected_version:detail.plan.current_version,sections:[{key:'plan_overview',title:'Plan overview',content:{text},items:[]}]};const run=async action=>{setBusy(action);setError('');try{if(action==='save')await saveProfessionPlan(detail.plan.id,payload);else await publishProfessionPlan(detail.plan.id);await onReload(detail.plan.id)}catch(reason){setError(reason.message||'Plan action failed.')}finally{setBusy('')}};return <div className="space-y-4"><section className="rounded-2xl border bg-white p-5"><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-wider text-blue-700">{label(detail.plan.plan_type)}</p><h4 className="mt-1 text-xl font-bold">Version {detail.plan.current_version} · {detail.plan.status}</h4></div><div className="flex gap-2"><button disabled={locked||busy} onClick={()=>run('save')} className="min-h-11 rounded-xl border px-4 font-semibold disabled:opacity-40">{busy==='save'?'Saving…':'Save draft'}</button><button disabled={locked||busy} onClick={()=>run('publish')} className="min-h-11 rounded-xl bg-slate-950 px-4 font-semibold text-white disabled:opacity-40">{locked?'Published':busy==='publish'?'Publishing…':'Publish'}</button></div></div>{error&&<p role="alert" className="mt-3 text-sm text-red-700">{error}</p>}<label className="mt-5 block text-sm font-semibold">Plan title<input disabled={locked} value={title} onChange={event=>setTitle(event.target.value)} className="mt-2 min-h-12 w-full rounded-xl border px-3 disabled:bg-slate-100"/></label><label className="mt-4 block text-sm font-semibold">Plan overview<textarea disabled={locked} value={text} onChange={event=>setText(event.target.value)} rows={7} className="mt-2 w-full rounded-xl border p-3 disabled:bg-slate-100"/></label>{locked&&<p className="mt-3 text-xs text-slate-500">Published versions are immutable.</p>}</section><ProfessionPlanPreview detail={{...detail,plan:{...detail.plan,title},sections:[{id:'preview',title:'Plan overview',content:{text}}]}}/></div>}

export function ProfessionPlans({clientId,profession}){const [items,setItems]=useState([]);const [detail,setDetail]=useState(null);const [state,setState]=useState('loading');const [error,setError]=useState('');const load=async(openId)=>{setState('loading');setError('');try{const history=await listProfessionPlans(clientId);setItems(history.items||[]);const id=openId||detail?.plan?.id;if(id)setDetail(await getProfessionPlan(id));setState('ready')}catch(reason){setError(reason.message||'Profession plans could not load.');setState('error')}};useEffect(()=>{void load()},[clientId]);const create=async()=>{const type=TYPE_BY_PROFESSION[profession];if(!type)return;try{const value=await createProfessionPlan({client_id:clientId,plan_type:type,title:`${label(type)}`,sections:[{key:'plan_overview',title:'Plan overview',content:{text:''},items:[]}]});await load(value.id)}catch(reason){setError(reason.message||'Plan could not be created.');setState('error')}};if(state==='loading')return <div role="status" className="grid min-h-40 place-items-center rounded-2xl bg-white"><Loader2 className="animate-spin"/><span className="sr-only">Loading profession plans</span></div>;if(state==='error')return <div role="alert" className="rounded-2xl bg-red-50 p-5 text-red-800">{error}<button onClick={()=>load()} className="ml-3 min-h-11 px-3 font-bold"><RefreshCw className="inline"/> Retry</button></div>;return <div className="space-y-5"><div className="flex items-center justify-between gap-3"><div><h3 className="text-xl font-bold">Profession plans</h3><p className="text-sm text-slate-500">Draft, save, preview, publish, and retain immutable history.</p></div><button onClick={create} className="min-h-11 rounded-xl bg-blue-700 px-4 font-semibold text-white">New plan</button></div>{detail?<ProfessionPlanEditor key={`${detail.plan.id}-${detail.plan.status}`} detail={detail} onReload={load}/>:<ProfessionPlanHistory items={items} onOpen={async id=>setDetail(await getProfessionPlan(id))}/>}</div>}
